package com.dentalcare.api.modules.contactinquiries.service;
import com.dentalcare.api.modules.contactinquiries.dto.request.*; import com.dentalcare.api.modules.contactinquiries.mapper.ContactInquiryMapper; import com.dentalcare.api.modules.contactinquiries.model.*; import com.dentalcare.api.modules.contactinquiries.repository.ContactInquiryRepository; import com.dentalcare.api.modules.users.repository.UserRepository; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class ContactInquiryServiceImplTests {
 @Test void createsNewInquiryWithBackendIdentityTimestampAndStatus(){var repo=mock(ContactInquiryRepository.class);var service=new ContactInquiryServiceImpl(repo,new ContactInquiryMapper(),mock(UserRepository.class),Clock.fixed(Instant.parse("2026-10-05T00:00:00Z"),ZoneOffset.UTC));when(repo.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(request("<script>x</script>"));assertThat(result.received()).isTrue();var cap=org.mockito.ArgumentCaptor.forClass(ContactInquiry.class);verify(repo).save(cap.capture());assertThat(cap.getValue().getStatus()).isEqualTo(ContactInquiryStatus.NEW);assertThat(cap.getValue().getId()).isNotNull();assertThat(cap.getValue().getCreatedAt()).isEqualTo(Instant.parse("2026-10-05T00:00:00Z"));assertThat(cap.getValue().getMessage()).isEqualTo("<script>x</script>");}
 @Test void rejectsPrivacyNotAccepted(){var service=new ContactInquiryServiceImpl(mock(ContactInquiryRepository.class),new ContactInquiryMapper(),mock(UserRepository.class),Clock.systemUTC());assertThatThrownBy(()->service.create(new CreateContactInquiryRequest("Ana","ana@test.com",null,ContactInquiryReason.GENERAL,"Hola",false))).isInstanceOf(com.dentalcare.api.exception.BadRequestException.class);}
 private CreateContactInquiryRequest request(String message){return new CreateContactInquiryRequest(" Ana ","ANA@TEST.COM"," 5555-1234 ",ContactInquiryReason.SERVICES,message,true);}
}
